import java.util.*;

class Solution {
  public List<String> mostVisitedPattern(String[] username, int[] timestamp, String[] website) {
    Integer[] order = new Integer[username.length];
    for (int i = 0; i < order.length; i++) order[i] = i;
    Arrays.sort(order, (a, b) -> Integer.compare(timestamp[a], timestamp[b]));
    Map<String, List<String>> visits = new HashMap<>(); // user -> websites in time order
    for (int i : order) visits.computeIfAbsent(username[i], k -> new ArrayList<>()).add(website[i]);
    Map<String, Integer> score = new HashMap<>();
    for (List<String> sites : visits.values()) {
      Set<String> patterns = new HashSet<>(); // each user counts a pattern once
      for (int a = 0; a < sites.size(); a++)
        for (int b = a + 1; b < sites.size(); b++)
          for (int c = b + 1; c < sites.size(); c++) patterns.add(sites.get(a) + " " + sites.get(b) + " " + sites.get(c));
      for (String p : patterns) score.merge(p, 1, Integer::sum);
    }
    String best = null;
    for (Map.Entry<String, Integer> e : score.entrySet()) {
      if (best == null || e.getValue() > score.get(best) || (e.getValue().equals(score.get(best)) && e.getKey().compareTo(best) < 0))
        best = e.getKey();
    }
    return Arrays.asList(best.split(" "));
  }
}
